#!/usr/bin/env python3
"""リソースパックの772対応を入れる（DetergentServer／yml）。

pack_format 64（リソースパック）／81（データパック）は Minecraft Wiki の
pack_format 表で確認した値。771の流儀をなぞる：771用が9番目に増えるのと
同じ形で、772用を増やす。
ResourcePackBuilder の772対応（build772／pack_format 64）は別途手書きする。
ResourcePackServer／ResourcePackMode の772対応は
patch-resourcepackserver-772.py／patch-resourcepackmode-772.py で入れる
（このスクリプトは DetergentServer／yml だけを触る。コンパイルには3つ全てが必要）。
各アンカーはファイル中にちょうど1回だけ現れること。
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent  # detergentmc-protocol/
PROTOCOL = ROOT / "src" / "main" / "java" \
    / "io" / "detergentmc" / "protocol"
CORE = ROOT.parent / "detergentmc-core" / "src" / "main" / "java" / "io" / "detergentmc" / "core"

DET = CORE / "DetergentServer.java"
YML = ROOT.parent / "detergentmc-core" / "src" / "main" / "resources" / "detergentmc.yml"


def edit(path, pairs):
    src = path.read_text(encoding="utf-8")
    for name, old, new in pairs:
        n = src.count(old)
        if n != 1:
            print(f"NG: {path.name} {name}: anchor が {n} 回見つかった（1回のはず）",
                  file=sys.stderr)
            sys.exit(1)
        src = src.replace(old, new, 1)
        print(f"OK: {path.name} {name}")
    path.write_text(src, encoding="utf-8")


